#!/usr/bin/env bash
set -euo pipefail

# Fase 7b -- Aprovechamiento real de pantalla + Planificación estilo Bringg
# (selección de pedidos -> planificar -> Rutas) + editar/eliminar en Clientes,
# Transportistas, Almacenes y Usuarios.
#
# 1) APROVECHAMIENTO DE PANTALLA (toda la aplicación):
#    - AppLayout.tsx: el contenido tenía un ancho máximo de 1152px (max-w-6xl)
#      centrado -- en un monitor ancho eso dejaba un margen enorme sin usar a
#      los lados, en TODAS las pantallas. Sube a 1680px.
#    - DispatchBoard.tsx (Despacho): la tabla/panel/mapa tenían alturas fijas
#      (520px/460px) que no se adaptaban -- con pocos datos (como en tus
#      capturas) quedaba un hueco vacío debajo de la tabla mientras el mapa se
#      veía pequeño. Ahora las tres columnas usan la altura real disponible en
#      pantalla (flex + altura calculada), así que crecen igual y el mapa por
#      fin se ve grande de verdad.
#    - PlannerMap.tsx: admite altura relativa (100%) además de en píxeles, para
#      poder rellenar esos contenedores -- quien ya lo usaba con un número
#      (Seguimiento, Tablero) sigue exactamente igual.
#
# 2) PLANIFICADOR REESTRUCTURADO -- estilo Bringg, en dos pasos:
#    - Pestaña "Planificación" (PlanificacionTab.tsx, nueva): lista con casillas
#      de los pedidos pendientes del almacén/fecha/servicio elegidos. Marcas los
#      que quieres incluir (o "seleccionar todos") y le das a "Planificar
#      automáticamente" -- mismo motor de la Fase 6 (OpenRouteService/VROOM),
#      ahora con selección explícita en vez de coger siempre los N de más
#      prioridad sin más control (routes.routes.ts: /auto-plan admite un nuevo
#      campo opcional orderIds).
#    - Pestaña "Rutas" (RutasTab.tsx, nueva): el resultado -- qué rutas salieron,
#      con qué transportista/vehículo/conductor (si ya lo tienen) y, desplegando
#      cada una, qué pedidos lleva y en qué orden, con un mapa al lado.
#    - Al planificar con éxito, se salta solo a "Rutas" para ver el resultado.
#    - "Despacho" no cambia de función -- sigue siendo el seguimiento en vivo
#      del día ya en marcha (mapa, panel de conductor, línea de tiempo); solo se
#      beneficia del arreglo de maquetación del punto 1.
#    - Esto SUSTITUYE a las pestañas "Tablero / Mapa" y "Lista" (quedan fuera de
#      la barra de pestañas, tal y como confirmaste) -- el código de Tablero/Mapa
#      (arrastrar y soltar) no se borra, solo deja de estar enlazado desde aquí.
#
# 3) EDITAR / ELIMINAR en los módulos que no lo tenían:
#    - Clientes: antes solo se podían dar de alta importando un Excel -- el
#      backend ya tenía alta/edición/baja manual desde hace tiempo (nunca se
#      usaba desde la pantalla). Ahora hay "+ Nuevo cliente", "Editar" y
#      "Eliminar" (baja lógica -- un cliente dado de baja nunca se borra de
#      verdad, para no romper pedidos históricos).
#    - Transportistas (pestaña "Empresa" de Flota y Transportistas): no tenía
#      NI alta -- ahora tiene "+ Nuevo transportista", "Editar" y "Eliminar"
#      (baja lógica; se añade el DELETE que le faltaba al backend).
#    - Almacenes: tenía alta pero no editar/eliminar -- añadidos ("Eliminar" es
#      baja lógica; se añade el DELETE que le faltaba al backend).
#    - Usuarios: tenía activar/desactivar pero no corregir nombre/email ni
#      cambiar roles sin borrar y crear de nuevo -- ahora hay "Editar" (no toca
#      el tipo de acceso ni la contraseña, que ya tienen su propio camino).
#
# Ningún cambio de schema.prisma -- todos los campos usados ya existían.
# Ejecutar desde la raíz del repo tms-production.

REPO_ROOT="$(pwd)"

mkdir -p "$REPO_ROOT/backend/src/modules/routes"
base64 -d > "$REPO_ROOT/backend/src/modules/routes/routes.routes.ts" <<'B64EOF'
